    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(seed == seed);
        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && address(this).balance >= beforeBal && c.depositsCount() == beforeCount);
    }

    receive() external payable {}
}

