// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 seed) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(seed == seed);
        uint beforeBal = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(c).balance == 0 && address(this).balance >= beforeBal && c.depositsCount() == beforeCount);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
